#!/bin/sh
# Uses assets generated by build_native.sh; keeps the standard ROM intact.
set -eu
cd "$(dirname "$0")/../.."
variant=nes-blend80-sp
rom_name=Monty-v06c-nes3-blend80-sp
extra_flag=
stable_flag=
seed_flag=
if test "${STABLE_COLORS:-1}" = 1; then
 stable_flag=-DNES_STABLE_COLORS
 python3 tools/nes/object_colors.py
fi
if test "${LADDER_LOW:-0}" = 1; then
 variant=nes-blend80-sp-white-ladder
 rom_name=Monty-v06c-nes3-blend80-sp-white-ladder
 extra_flag=-DNES_LADDER_LOW
fi
if test "${SEED_CACHE:-0}" = 1; then
 variant=$variant-seeds
 rom_name=$rom_name-seeds
 seed_flag=-DNES_ENEMY_SEEDS
fi
mkdir -p "build/$variant"
(
 cd src/native
 ../../tools/sjasmplus --nologo --i8080 -DNES_JOE_3COLOR -DNES_JOE_BLEND80 -DNES_JOE_SP_RESTORE $extra_flag $stable_flag $seed_flag --sym=../../build/native/monty.sym game.asm
)
cp build/native/monty.bin build/native/monty.sym "build/$variant/"
B="build/$variant" node tools/bench/joe-restore-sp.js
B="build/$variant" node tools/bench/joe-poses.js
if test "${STABLE_COLORS:-1}" = 1; then
 B="build/$variant" node tools/bench/nes-cheat-pack.js
 B="build/$variant" node tools/bench/nes-cheats.js
 B="build/$variant" node tools/bench/nes-joystick.js
 B="build/$variant" node tools/bench/nes-pacing.js
 B="build/$variant" node tools/bench/nes-joe-cadence.js
 B="build/$variant" node tools/bench/nes-hud.js
 B="build/$variant" node tools/bench/nes-title-font.js
 python3 tools/nes/treasure_reference.py
 B="build/$variant" node tools/bench/nes-treasure.js
 python3 tools/nes/treasure_entry_reference.py
 B="build/$variant" node tools/bench/nes-platform-entry-ref.js
 B="build/$variant" node tools/bench/nes-treasure-entry.js
 B="build/$variant" node tools/bench/nes-treasure-entry-live.js
 B="build/$variant" node tools/bench/nes-item-row.js
 python3 tools/nes/treasure_motion_reference.py
 B="build/$variant" node tools/bench/nes-treasure-motion.js
 B="build/$variant" node tools/bench/nes-treasure-jump.js
 B="build/$variant" node tools/bench/nes-treasure-jump-live.js
 B="build/$variant" node tools/bench/nes-treasure-sound.js
 B="build/$variant" node tools/bench/nes-treasure-live.js
 B="build/$variant" node tools/bench/nes-treasure-theme.js
 B="build/$variant" node tools/bench/nes-climb-centering.js
 B="build/$variant" node tools/bench/nes-title-animation.js
 B="build/$variant" node tools/bench/nes-title-raster.js
 N=400 B="build/$variant" node tools/bench/nes-pacing-raster.js
 B="build/$variant" node tools/bench/nes-title-palette.js
 B="build/$variant" node tools/bench/nes-restart.js
 B="build/$variant" node tools/bench/nes-start-rope.js
 B="build/$variant" node tools/bench/nes-stable-items.js
 B="build/$variant" node tools/bench/nes-stable-torch-live.js
 B="build/$variant" node tools/bench/nes-spider-colors.js
 B="build/$variant" node tools/bench/nes-snake-video.js
 node tools/bench/nes-snake-delta.js "build/$variant"
 B="build/$variant" node tools/bench/nes-snake-covered.js
 B="build/$variant" node tools/bench/nes-amulet-snake.js
 B="build/$variant" node tools/bench/nes-gameover-colors.js
 B="build/$variant" node tools/bench/nes-respawn-start.js
 # Original NES execution supersedes the earlier MSX cap-proximity fixtures.
 python3 tools/nes/physics_reference.py
 python3 tools/nes/physics_map_reference.py
 python3 tools/nes/physics_boundary_reference.py
 B="build/$variant" VERIFY=1 node tools/bench/nes-physics-audit.js
 B="build/$variant" VERIFY=1 REF=build/nes-physics-audit/map-reference.json OUT=build/nes-physics-audit/map-native.json node tools/bench/nes-physics-audit.js
 B="build/$variant" node tools/bench/nes-physics-boundaries.js
 B="build/$variant" node tools/bench/nes-full.js
 python3 tools/nes/platform_reference.py
 B="build/$variant" node tools/bench/nes-platform-physics.js
 B="build/$variant" node tools/bench/nes-inventory-art.js
 B="build/$variant" node tools/bench/nes-conveyor-colors.js
 B="build/$variant" node tools/bench/nes-platform-transitions.js
 node tools/bench/nes-platform-phase.js "build/$variant"
 B="build/$variant" node tools/bench/nes-laser-video.js
 B="build/$variant" node tools/bench/nes-live-code-bound.js
 B="build/$variant" node tools/bench/nes-live-capacity.js
 B="build/$variant" node tools/bench/nes-cache-lifetime.js
fi
if test "${SEED_CACHE:-0}" = 1; then
 node tools/bench/nes-enemy-seeds.js "build/$variant"
fi
cp "build/$variant/monty.bin" "rom/$rom_name-core.r0m"
python3 tools/nes/build_splash.py --build "build/$variant" --output "rom/$rom_name.r0m" --quick
B="build/$variant" node tools/bench/nes-splash.js
